      if (!inner) return;
      const peerLines = {};
      for (const p of (cachedPeers || [])) {
        if ((p.userId || p.id) !== userId && p.cursor && p.cursor.filePath === activeFile && p.cursor.line) {
          peerLines[p.cursor.line] = p.color || ""#3b82f6"";
        }
      }
      const count = Math.max(1, lineTops.length);
      const key = count + ""|"" + lineHeights.join("","") + ""|"" + JSON.stringify(peerLines);
      if (key === lastGutterKey) return;
      lastGutterKey = key;
      const out = [];
      for (let i = 1; i <= count; i++) {
        const dotCol = peerLines[i];
        const dot = dotCol ? `<span style=""width:5px;height:5px;margin-top:7px;border-radius:50%;background:${escapeHtml(dotCol)};display:inline-block""></span>` : """";
        const h = lineHeights[i - 1] || LINE_H;
        out.push(`<div class=""gutter-line""${h !== LINE_H ? ` style=""height:${h}px""` : """"}>${dot}<span>${i}</span></div>`);
      }
      inner.innerHTML = out.join("""");
    }

    function renderInEditorCollaboratorBands() {
      const overlay = document.getElementById(""editorCollabOverlay"");
      if (!overlay) return;
      const bands = [];
      const allActive = (cachedPeers || []).filter(p => p.cursor && p.cursor.filePath === activeFile && (p.userId || p.id) !== userId);
      for (const p of allActive) {
        const pid = p.userId || p.id;
        const isAI = pid === AI_USER_ID || p.role === ""AI Agent"";
        const c = p.cursor;
        const startLn = Math.max(1, c.line || 1);
        const endLn = Math.max(startLn, c.endLine || startLn);
        const topPx = TOP_PAD + lineTop(startLn);
        const heightPx = lineSpan(startLn, endLn);
        const col = escapeHtml(p.color || ""#64748B"");
        const statusSuffix = isAI
          ? (c.isTyping ? ` · กำลังแก้ Ln ${startLn}` : (p.aiStatusText ? ` · ${p.aiStatusText}` : ` · Ln ${startLn}`))
          : (c.isTyping ? ` · กำลังแก้ Ln ${startLn}` : ` · Ln ${startLn}`);
        bands.push(`<div class=""collab-line-band"" style=""top:${topPx}px;height:${heightPx}px;background:${col}18;border-left-color:${col}"">
          <div class=""collab-line-tag"" style=""background:rgba(18,20,24,0.94);border:1px solid rgba(255,255,255,0.14)"">● ${escapeHtml(p.displayName)}${escapeHtml(statusSuffix)}</div>
        </div>`);
      }
      overlay.innerHTML = bands.join("""");
    }

    // Transforms instead of scrollTop on overflow:hidden layers: those clamp at their own (shorter) scroll
    // range, which made the numbers and colours drift from the text near the end of long files.
    function syncEditorScroll() {
      const area = document.getElementById(""codeArea"");
      if (!area) return;
      const x = area.scrollLeft, y = area.scrollTop;
      document.getElementById(""codeHighlight"").style.transform = `translate(${-x}px, ${-y}px)`;
      document.getElementById(""editorCollabOverlay"").style.transform = `translateY(${-y}px)`;
      document.getElementById(""gutterInner"").style.transform = `translateY(${-y}px)`;
    }

    function scrollToLine(lineNum) {
      const area = document.getElementById(""codeArea"");
      if (!area) return;
      const targetY = Math.max(0, lineTop(lineNum) - (area.clientHeight * 0.35));
      area.scrollTo({ top: targetY, behavior: ""smooth"" });
    }

    function computeCursorPos() {
      const area = document.getElementById(""codeArea"");
      if (!activeFile || !area) return null;
      const val = area.value || """";
      const start = area.selectionStart || 0;
      const end = area.selectionEnd || start;
      const beforeStart = val.slice(0, start).split(""\n"");
      const line = beforeStart.length;
      const column = beforeStart[beforeStart.length - 1].length + 1;
      let endLine = null, endColumn = null;
      if (end > start) {
        const beforeEnd = val.slice(0, end).split(""\n"");
        endLine = beforeEnd.length;
        endColumn = beforeEnd[beforeEnd.length - 1].length + 1;
      }
      return { filePath: activeFile, line, column, endLine, endColumn, isTyping };
    }

    // Applies a collaborator's (already transformed) operation to the textarea: the caret and selection
    // are mapped through it and the scroll position is kept.
    function applyRemoteOperation(area, op, before, after) {
      if (!area) return;
      if (area.value !== before) {
        // Unsent keystrokes: flush them first so nothing typed is lost, then rebase.
        submitLocalText(activeFile, area.value);
        const st = otFiles[activeFile];
        if (st) { area.value = st.shadow; refreshEditorView(); }
        return;
      }
      const focused = document.activeElement === area;
      const selStart = area.selectionStart || 0, selEnd = area.selectionEnd || 0, dir = area.selectionDirection;
      const scrollTop = area.scrollTop, scrollLeft = area.scrollLeft;
      area.value = after;
      if (focused) area.setSelectionRange(OT.transformIndex(op, selStart), OT.transformIndex(op, selEnd), dir || ""none"");
      area.scrollTop = scrollTop; area.scrollLeft = scrollLeft;
      refreshEditorView();
    }

    function toggleFollowPeer(pid, ev) {
      if (ev) ev.stopPropagation();
      if (followingPeerId === pid) {
        followingPeerId = null;
        lastFollowedState = """";
      } else {
        followingPeerId = pid;
        lastFollowedState = """";
        applyWebFollowIfNeeded(true);
      }
      renderPeersAndCursors();
    }

    function followAITeammate() {
      const aiPeer = (cachedPeers || []).find(p => (p.userId || p.id) === AI_USER_ID || p.role === ""AI Agent"");
      const targetId = aiPeer ? (aiPeer.userId || aiPeer.id) : AI_USER_ID;
      toggleFollowPeer(targetId, null);
    }

    function applyWebFollowIfNeeded(forceJump) {
      const banner = document.getElementById(""followBanner"");
      if (!followingPeerId) {
        if (banner) banner.style.display = ""none"";
        return;
      }
      const target = (cachedPeers || []).find(p => (p.userId || p.id) === followingPeerId);
      if (!target) {
        if (banner) banner.style.display = ""none"";
        return;
      }
      const c = target.cursor;
      const fileLabel = c && c.filePath ? `${c.filePath.split('/').pop()}:${c.line || 1}` : (target.aiStatusText || ""In workspace"");
      if (banner) {
        banner.style.display = ""inline-flex"";
        banner.innerHTML = `<span>👁 Following <strong>${escapeHtml(target.displayName)}</strong> · ${escapeHtml(fileLabel)}</span> <button class=""btn"" style=""padding:1px 6px;font-size:10px"" onclick=""toggleFollowPeer('${escapeHtml(followingPeerId)}', event)"">Unfollow</button>`;
      }
      if (c && c.filePath) {
        const stateKey = `${c.filePath}:${c.line || 1}`;
        if (forceJump || stateKey !== lastFollowedState) {
          lastFollowedState = stateKey;
          if (c.filePath !== activeFile) {
            openFile(c.filePath, c.line || 1);
          } else {
            scrollToLine(c.line || 1);
          }
        }
      }
    }

    function connectWS() {
      try {
        const proto = location.protocol === ""https:"" ? ""wss:"" : ""ws:"";
        ws = new WebSocket(`${proto}//${location.host}${BASE_PATH}/ws/collab?code=${encodeURIComponent(ROOM_CODE)}`);
        ws.onopen = () => {
          wsFailCount = 0;
          document.getElementById(""wsStatusBadge"").textContent = ""WS REALTIME"";
          ws.send(JSON.stringify({
            type: ""hello"",
            code: ROOM_CODE,
            userId,
            displayName,
            color: myColor,
            role: ""Web"",
            caps: [""ot1""]
          }));
          // Catch up on commits missed while disconnected, then resend anything still unacknowledged.
          for (const path of Object.keys(otFiles)) {
            const st = otFiles[path];
            ws.send(JSON.stringify({ type: ""opSync"", path, since: st.revision }));
            if (st.outstanding) sendOperation(path, st);
          }
          sendPresenceWS();
        };
        ws.onmessage = (ev) => {
          try {
            const msg = JSON.parse(ev.data);
            if ((msg.type === ""assignedIdentity"" || msg.type === ""welcome"") && (msg.color || msg.assignedColor)) {
              myColor = msg.color || msg.assignedColor;
              localStorage.setItem(""mc_collab_color"", myColor);
              renderPeersAndCursors();
            } else if (msg.type === ""participants"" && Array.isArray(msg.participants)) {
              cachedPeers = msg.participants;
              renderPeersAndCursors();
              renderFileTree();
              applyWebFollowIfNeeded(false);
            } else if (msg.type === ""mouse"" && msg.userId && msg.userId !== userId) {
              let idx = cachedPeers.findIndex(p => (p.userId || p.id) === msg.userId);
              if (idx < 0) {
                cachedPeers.push({ userId: msg.userId, displayName: msg.displayName || ""Teammate"", color: msg.color || ""#3B82F6"", role: msg.role || ""Editor"", isOnline: true });
                idx = cachedPeers.length - 1;
              }
              cachedPeers[idx].mouse = { x: msg.x, y: msg.y, surface: msg.surface || ""editor"", activeFile: msg.activeFile || """", activeLine: msg.activeLine || 0 };
              renderPeersAndCursors();
            } else if (msg.type === ""cursor"" && msg.userId && msg.userId !== userId) {
              let idx = cachedPeers.findIndex(p => (p.userId || p.id) === msg.userId);
              if (idx < 0) {
                cachedPeers.push({ userId: msg.userId, displayName: msg.displayName || ""Teammate"", color: msg.color || ""#3B82F6"", role: msg.role || ""Editor"", isOnline: true });
                idx = cachedPeers.length - 1;
              }
              cachedPeers[idx].cursor = { filePath: msg.filePath, line: msg.line, column: msg.column, endLine: msg.endLine, endColumn: msg.endColumn, isTyping: msg.isTyping };
              if (msg.aiStatusText !== undefined) cachedPeers[idx].aiStatusText = msg.aiStatusText;
              if (msg.isAIActive !== undefined) cachedPeers[idx].isAIActive = msg.isAIActive;
              renderPeersAndCursors();
              renderFileTree();
              applyWebFollowIfNeeded(false);
            } else if (msg.type === ""op"" && msg.path) {
              handleCommit(msg);
            } else if (msg.type === ""opError"" && msg.path) {
              handleOTError(msg);
            } else if (msg.type === ""fileBuffer"" && msg.path) {
              if (!cachedFiles.some(f => f.relativePath === msg.path)) syncState();
            } else if (msg.type === ""chat"" && msg.message) {
              if (!cachedChats.some(c => c.id === msg.id)) {
                cachedChats.push({ id: msg.id || String(Date.now()), userId: msg.userId, displayName: msg.displayName || ""Teammate"", userColor: msg.userColor || ""#60a5fa"", message: msg.message });
                renderChatMessages();
              }
            } else if (msg.type === ""fsEvent"") {
              syncState();
            }
          } catch (e) {}
        };
        ws.onclose = () => {
          wsFailCount += 1;
          document.getElementById(""wsStatusBadge"").textContent = BASE_PATH ? ""CLOUD RELAY LIVE"" : ""LIVE SYNC"";
          // Keep retrying (backing off); HTTP polling carries edits meanwhile.
          setTimeout(connectWS, Math.min(30000, 1500 * Math.pow(2, Math.min(wsFailCount, 5))));
        };
      } catch (e) {}
    }

    function sendPresenceWS() {
      if (!ws || ws.readyState !== 1) return;
      const rect = document.getElementById(""workspaceArea"").getBoundingClientRect();
      const x = rect.width > 0 ? Math.max(0, Math.min(1, (localMouse.x - rect.left) / rect.width)) : 0.5;
      const y = rect.height > 0 ? Math.max(0, Math.min(1, (localMouse.y - rect.top) / rect.height)) : 0.5;
      const cur = computeCursorPos();
      if (localMouse.visible) {
        ws.send(JSON.stringify({
          type: ""mouse"",
          userId,
          displayName,
          color: myColor,
          role: ""Web"",
          x,
          y,
          surface: ""web"",
          activeFile: activeFile || """",
          activeLine: cur ? cur.line : 0,
          isPressing: false
        }));
      }
      if (cur) {
        ws.send(JSON.stringify({
          type: ""cursor"",
          userId,
          displayName,
          color: myColor,
          role: ""Web"",
          filePath: cur.filePath,
          line: cur.line,
          column: cur.column,
          endLine: cur.endLine,
          endColumn: cur.endColumn,
          isTyping: !!cur.isTyping
        }));
      }
    }

    window.addEventListener(""mousemove"", (e) => {
      localMouse = { x: e.clientX, y: e.clientY, visible: true };
      renderPeersAndCursors();
      const now = performance.now();
      if (now - lastMouseSent > 35) {
        lastMouseSent = now;
        sendPresenceWS();
      }
    });

    function saveName() {
      displayName = document.getElementById(""nameInput"").value.trim() || displayName;
      localStorage.setItem(""mc_collab_name"", displayName);
      sendPresenceWS();
      syncState();
    }

    async function joinRoom() {
      try {
        const res = await fetch(apiUrl(""/api/collab/join""), {
          method: ""POST"",
          headers: {""Content-Type"": ""application/json""},
          body: JSON.stringify({ code: ROOM_CODE, userId, displayName, color: myColor, role: ""Web"" })
        });
        const d = await res.json();
        if (d.assignedColor) {
          myColor = d.assignedColor;
          localStorage.setItem(""mc_collab_color"", myColor);
        }
      } catch (e) {}
      await syncState();
      connectWS();
    }

    async function openFile(path, jumpLine) {
      const area = document.getElementById(""codeArea"");
      if (activeFile && otFiles[activeFile] && area.value !== otFiles[activeFile].shadow) submitLocalText(activeFile, area.value);
      activeFile = path;
      const shortName = path.split(""/"").pop();
      document.getElementById(""activeFileIcon"").innerHTML = getFileIconSVG(shortName);
      document.getElementById(""activeFileName"").textContent = path;
      renderFileTree();
      let st = otFiles[path];
      if (!st) {
        try {
          const res = await fetch(apiUrl(""/api/collab/file?path="" + encodeURIComponent(path)));
          const d = await res.json();
          if (activeFile !== path) return;
          st = otFiles[path] || otState(path, d.content || """", d.revision || 1);
          if (ws && ws.readyState === 1) ws.send(JSON.stringify({ type: ""opSync"", path, since: st.revision }));
        } catch (e) { return; }
      }
      area.value = st.shadow;
      area.scrollTop = 0; area.scrollLeft = 0;
      refreshEditorView(true);
      setSyncLabel();
      if (jumpLine && jumpLine > 1) scrollToLine(jumpLine);
      sendPresenceWS();
    }

    async function postFsEvent(op, path, content) {
      await fetch(apiUrl(""/api/collab/fs-event""), {
        method: ""POST"",
        headers: { ""Content-Type"": ""application/json"" },
        body: JSON.stringify({ op, path, content, userId, displayName })
      });
    }
    function cleanNewPath(raw) {
      return String(raw || """").replace(/\\/g, ""/"").split(""/"").filter(p => p && p !== ""."" && p !== "".."").join(""/"");
    }
    function currentFolderPrefix() {
      if (!activeFile || !activeFile.includes(""/"")) return """";
      return activeFile.slice(0, activeFile.lastIndexOf(""/"") + 1);
    }
    async function promptNewFile() {
      const path = cleanNewPath(prompt(""New file (path inside the workspace):"", currentFolderPrefix()));
      if (!path) return;
      if (cachedFiles.some(f => f.relativePath === path)) { openFile(path); return; }
      await postFsEvent(""write"", path, """");
      await syncState();
      openFile(path);
    }
    async function promptNewFolder() {
      const path = cleanNewPath(prompt(""New folder (path inside the workspace):"", currentFolderPrefix()));
      if (!path) return;
      await postFsEvent(""mkdir"", path);
      await syncState();
    }

    const codeAreaEl = document.getElementById(""codeArea"");
    let typingTimer = null;
    function onLocalInput() {
      if (!activeFile) return;
      isTyping = true;
      submitLocalText(activeFile, codeAreaEl.value);
      refreshEditorView();
      sendPresenceWS();
      clearTimeout(typingTimer);
      typingTimer = setTimeout(() => { isTyping = false; sendPresenceWS(); }, 900);
    }
    function insertAtSelection(text) {
      // execCommand keeps the browser's undo stack; setRangeText is the fallback.
      if (!(document.execCommand && document.execCommand(""insertText"", false, text))) {
        codeAreaEl.setRangeText(text, codeAreaEl.selectionStart, codeAreaEl.selectionEnd, ""end"");
        onLocalInput();
      }
    }
    const INDENT = ""  "";
    codeAreaEl.addEventListener(""keydown"", (e) => {
      if (e.isComposing) return;
      const v = codeAreaEl.value, s0 = codeAreaEl.selectionStart, s1 = codeAreaEl.selectionEnd;
      if ((e.metaKey || e.ctrlKey) && e.key.toLowerCase() === ""s"") { e.preventDefault(); setSyncLabel(); return; }
      if (e.key === ""Tab"") {
        e.preventDefault();
        const lineStart = v.lastIndexOf(""\n"", s0 - 1) + 1;
        if (!e.shiftKey && s0 === s1) { insertAtSelection(INDENT); return; }
        const blockEnd = s1 > s0 && v[s1 - 1] === ""\n"" ? s1 - 1 : s1;
        const lines = v.slice(lineStart, blockEnd).split(""\n"");
        let removedFirst = 0, delta = 0;
        const changed = lines.map((ln, i) => {
          if (e.shiftKey) {
            const cut = ln.startsWith(INDENT) ? INDENT.length : (ln.startsWith(""\t"") || ln.startsWith("" "") ? 1 : 0);
            if (i === 0) removedFirst = cut;
            delta -= cut;
            return ln.slice(cut);
          }
          delta += INDENT.length;
          return INDENT + ln;
        }).join(""\n"");
        codeAreaEl.setSelectionRange(lineStart, blockEnd);
        insertAtSelection(changed);
        const firstShift = e.shiftKey ? -Math.min(removedFirst, s0 - lineStart) : INDENT.length;
        codeAreaEl.setSelectionRange(Math.max(lineStart, s0 + firstShift), Math.max(lineStart, s1 + delta));
        return;
      }
      if (e.key === ""Enter"" && !e.shiftKey && !e.metaKey && !e.ctrlKey && !e.altKey) {
        const lineStart = v.lastIndexOf(""\n"", s0 - 1) + 1;
        const indent = (v.slice(lineStart, s0).match(/^[ \t]*/) || [""""])[0];
        const prevChar = v.slice(lineStart, s0).trimEnd().slice(-1);
        const extra = ""{[(:"".includes(prevChar) && prevChar !== """" ? INDENT : """";
        e.preventDefault();
        insertAtSelection(""\n"" + indent + extra);
      }
    });
    codeAreaEl.addEventListener(""scroll"", syncEditorScroll);
    codeAreaEl.addEventListener(""input"", onLocalInput);
    codeAreaEl.addEventListener(""compositionend"", onLocalInput);
    [""keyup"", ""mouseup"", ""click"", ""select""].forEach(evName => {
      codeAreaEl.addEventListener(evName, () => sendPresenceWS());
    });
    window.addEventListener(""resize"", () => refreshEditorView(true));

    function toggleFolder(dir) {
      if (collapsedFolders.has(dir)) collapsedFolders.delete(dir);
      else collapsedFolders.add(dir);
      renderFileTree();
    }

    function renderFileTree() {
      const folderSet = new Set(cachedDirs || []);
      for (const f of cachedFiles) {
        const parts = (f.relativePath || """").split(""/"");
        for (let i = 1; i < parts.length; i++) {
          folderSet.add(parts.slice(0, i).join(""/""));
        }
      }
      const entries = [];
      for (const d of folderSet) entries.push({ type: ""dir"", path: d });
      for (const f of cachedFiles) entries.push({ type: ""file"", path: f.relativePath, file: f });
      entries.sort((a, b) => a.path.localeCompare(b.path));

      document.getElementById(""fileCountLabel"").textContent = cachedFiles.length + "" files"";
      const html = [];
      for (const item of entries) {
        const parts = item.path.split(""/"");
        let hidden = false;
        for (let i = 1; i < parts.length; i++) {
          if (collapsedFolders.has(parts.slice(0, i).join(""/""))) { hidden = true; break; }
        }
        if (hidden) continue;
        const depth = parts.length - 1;
        const pad = 8 + depth * 14;
        const name = parts[parts.length - 1];
        if (item.type === ""dir"") {
          const isClosed = collapsedFolders.has(item.path);
          const dirPeers = cachedPeers.filter(p => (p.userId || p.id) !== userId && p.cursor && p.cursor.filePath && p.cursor.filePath.startsWith(item.path + ""/""));
          const dots = dirPeers.slice(0, 3).map(p => `<span class=""dot"" style=""width:6px;height:6px;background:${escapeHtml(p.color)}""></span>`).join("""");
          html.push(`<div class=""folder-row"" style=""padding-left:${pad}px"" onclick=""toggleFolder('${item.path.replace(/'/g, ""\\'"")}')"">
            <span style=""font-size:9px;width:10px;color:var(--muted)"">${isClosed ? '▶' : '▼'}</span>
            <span class=""file-icon-wrap"">${getFolderIconSVG(name, isClosed)}</span>
            <span style=""overflow:hidden;text-overflow:ellipsis;white-space:nowrap"">${escapeHtml(name)}</span>
            <span style=""margin-left:auto;display:flex;gap:3px"">${dots}</span>
          </div>`);
        } else {
          const filePeers = cachedPeers.filter(p => (p.userId || p.id) !== userId && p.cursor && p.cursor.filePath === item.path);
          const topPeer = filePeers[0];
          const badge = topPeer
            ? `<span class=""badge"" style=""font-size:9.5px;padding:1px 5px;border-color:rgba(255,255,255,0.12);color:var(--secondary);background:rgba(255,255,255,0.05)"">${escapeHtml(topPeer.displayName)}:${topPeer.cursor.line || 1}</span>`
            : """";
          html.push(`<div class=""file-row ${item.path === activeFile ? 'active' : ''}"" style=""padding-left:${pad + 14}px"" onclick=""openFile('${item.path.replace(/'/g, ""\\'"")}')"">
            <div class=""file-item-left"">
              <span class=""file-icon-wrap"">${getFileIconSVG(name)}</span>
              <span style=""overflow:hidden;text-overflow:ellipsis;white-space:nowrap"">${escapeHtml(name)}</span>
            </div>
            ${badge}
          </div>`);
        }
      }
      document.getElementById(""fileList"").innerHTML = html.join("""");
    }

    function renderPeersAndCursors() {
      const peers = cachedPeers || [];
      document.getElementById(""peerCountBadge"").textContent = Math.max(1, peers.length) + "" online"";
      document.getElementById(""peerList"").innerHTML = peers.map(p => {
        const pid = p.userId || p.id;
        const isAI = pid === AI_USER_ID || p.role === ""AI Agent"";
        const isFollow = followingPeerId === pid;
        const c = p.cursor;
        let act = c && c.filePath
          ? `${c.isTyping ? 'กำลังแก้ ' : ''}${c.filePath.split('/').pop()}:${c.line || 1}`
          : (p.mouse && p.mouse.activeFile ? p.mouse.activeFile.split('/').pop() : 'Browsing workspace');
        if (isAI && p.aiStatusText) {
          act = c && c.filePath ? `${p.aiStatusText} · ${c.filePath.split('/').pop()}:${c.line || 1}` : p.aiStatusText;
        }
        const clickAttr = c && c.filePath ? `onclick=""openFile('${c.filePath.replace(/'/g, ""\\'"")}', ${c.line || 1})""` : """";
        const followBtn = pid !== userId
          ? `<button class=""follow-btn ${isFollow ? 'active' : ''}"" onclick=""toggleFollowPeer('${escapeHtml(pid)}', event)"">${isFollow ? 'Following' : 'Follow'}</button>`
          : """";
        const roleBadge = isAI
          ? `<span class=""badge"" style=""font-size:9px;padding:1px 5px;background:rgba(255,255,255,0.06);border-color:rgba(255,255,255,0.12);color:var(--secondary)"">AGENT</span>`
          : `<span style=""color:var(--muted);font-weight:400"">(${escapeHtml(p.role)})</span>`;
        return `<div class=""peer-row ${isAI ? 'ai-peer' : ''} ${isFollow ? 'following' : ''}"" ${clickAttr}>
          <span class=""dot"" style=""background:${escapeHtml(p.color || '#64748b')}""></span>
          <div style=""min-width:0;flex:1"">
            <div style=""font-weight:600;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;display:flex;align-items:center;gap:5px"">
              <span>${escapeHtml(p.displayName)}${pid === userId ? ' (You)' : ''}</span>
              ${roleBadge}
            </div>
            <div style=""font-size:10.5px;color:var(--secondary);white-space:nowrap;overflow:hidden;text-overflow:ellipsis"">${escapeHtml(act)}</div>
          </div>
          ${followBtn}
        </div>`;
      }).join("""");

      const sameFilePeers = peers.filter(p => (p.userId || p.id) !== userId && p.cursor && p.cursor.filePath === activeFile);
      document.getElementById(""activeEditorsIndicator"").innerHTML = sameFilePeers.map(p => {
        return `<span style=""color:var(--secondary);font-weight:500"">● ${escapeHtml(p.displayName)} (Ln ${p.cursor.line || 1})</span>`;
      }).join("" &nbsp; "");

      renderGutter();
      renderInEditorCollaboratorBands();

      const rect = document.getElementById(""workspaceArea"").getBoundingClientRect();
      const cursorsHtml = [];
      for (const p of peers) {
        const pid = p.userId || p.id;
        if (pid === userId || !p.mouse) continue;
        const mx = p.mouse.x !== undefined ? p.mouse.x : (p.mouse.normX !== undefined ? p.mouse.normX : 0.5);
        const my = p.mouse.y !== undefined ? p.mouse.y : (p.mouse.normY !== undefined ? p.mouse.normY : 0.5);
        const px = rect.left + mx * rect.width;
        const py = rect.top + my * rect.height;
        const col = escapeHtml(p.color || ""#64748b"");
        const sub = p.cursor && p.cursor.filePath ? ` · ${p.cursor.filePath.split('/').pop()}:${p.cursor.line || 1}` : """";
        cursorsHtml.push(`<div class=""remote-cursor"" style=""transform:translate(${px.toFixed(1)}px, ${py.toFixed(1)}px)"">
          <svg width=""16"" height=""18"" viewBox=""0 0 16 18"" fill=""none""><path d=""M1 1L6.2 15.5L8.7 9.6L14.8 7.5L1 1Z"" fill=""${col}"" stroke=""#fff"" stroke-width=""1.3""/></svg>
          <div class=""cursor-pill"" style=""background:rgba(18,20,24,0.95);border:1px solid rgba(255,255,255,0.14)"">● ${escapeHtml(p.displayName)}${escapeHtml(sub)}</div>
        </div>`);
      }
      if (localMouse.visible && localMouse.x > 0) {
        cursorsHtml.push(`<div class=""remote-cursor"" style=""transform:translate(${(localMouse.x + 14).toFixed(1)}px, ${(localMouse.y + 16).toFixed(1)}px);transition:none;opacity:0.88"">
          <div class=""cursor-pill"" style=""background:rgba(18,20,24,0.95);border:1px solid rgba(255,255,255,0.14);margin:0;font-size:10px"">● ${escapeHtml(displayName)} (You)</div>
        </div>`);
      }
      document.getElementById(""cursorLayer"").innerHTML = cursorsHtml.join("""");
    }

    function renderChatMessages() {
      const box = document.getElementById(""chatMsgs"");
      if (!box) return;
      box.innerHTML = (cachedChats || []).map(c => {
        const isAI = c.userId === AI_USER_ID || c.displayName === ""MicroCode AI"";
        return `<div class=""chat-msg-card ${isAI ? 'ai-msg' : ''}"">
          <strong style=""color:#f3f4f6"">${escapeHtml(c.displayName)}:</strong>
          <span>${escapeHtml(c.message)}</span>
        </div>`;
      }).join("""");
      box.scrollTop = box.scrollHeight;
    }

    function prefillAIChat() {
      const inp = document.getElementById(""chatInput"");
      if (!inp) return;
      if (!inp.value.trim().toLowerCase().startsWith(""@ai"")) {
        inp.value = ""@ai "" + inp.value;
      }
      inp.focus();
    }

    async function sendChat() {
      const inp = document.getElementById(""chatInput"");
      const text = inp.value.trim();
      if (!text) return;
      inp.value = """";
      await fetch(apiUrl(""/api/collab/chat""), {
        method: ""POST"",
        headers: {""Content-Type"": ""application/json""},
        body: JSON.stringify({ userId, displayName, color: myColor, message: text })
      });
      syncState();
    }

    async function promptNewTask() {
      const title = prompt(""Shared Task Title:"");
      if (!title) return;
      const objective = prompt(""Task Objective / Scope:"") || """";
      await fetch(apiUrl(""/api/collab/task""), {
        method: ""POST"",
        headers: {""Content-Type"": ""application/json""},
        body: JSON.stringify({ action: ""create"", title, objective, scope: activeFile, author: displayName })
      });
      syncState();
    }

    async function syncState() {
      try {
        const res = await fetch(apiUrl(""/api/collab/sync""), {
          method: ""POST"",
          headers: {""Content-Type"": ""application/json""},
          body: JSON.stringify({
            userId,
            displayName,
            color: myColor,
            role: ""Web"",
            cursor: computeCursorPos()
          })
        });
        const s = await res.json();
        document.getElementById(""wsTitle"").textContent = ""MicroCode · "" + (s.workspaceName || ""Workspace"");
        cachedPeers = s.participants || [];
        cachedFiles = s.sharedFiles || [];
        cachedDirs = s.sharedDirectories || [];
        renderFileTree();
        renderPeersAndCursors();
        applyWebFollowIfNeeded(false);

        if (!activeFile && cachedFiles.length > 0) {
          openFile(cachedFiles[0].relativePath);
        }

        const tasks = JSON.parse(s.teamTasksJSON || ""[]"");
        document.getElementById(""taskList"").innerHTML = tasks.map(t =>
          `<div class=""peer-row"" style=""flex-direction:column;align-items:flex-start;gap:3px"">
            <div style=""font-weight:600;color:var(--text)"">${escapeHtml(t.title)}</div>
            <div style=""font-size:10.5px;color:var(--secondary)"">${escapeHtml(t.status)} · Owner: ${escapeHtml(t.owner)}</div>
          </div>`
        ).join("""") || `<div style=""padding:8px;font-size:11px;color:var(--muted)"">No shared tasks</div>`;

        cachedChats = s.chatMessages || [];
        renderChatMessages();
      } catch (e) {}
    }

    joinRoom();
    setInterval(syncState, 1400);
  </script>
</body>
</html>";

        /// <summary>buildOpenInMicroCodeHTML (the /join invite page): {{CODE_JSON}}, {{NAME_JSON}}, {{DOWNLOAD_JSON}} (JSON
        /// arrays from a serializer), {{BROWSER_ALLOWED}} (true / false).</summary>
        public const string OpenInApp = @"<!DOCTYPE html>
<html lang=""en"">
<head>
<meta charset=""utf-8"">
<meta name=""viewport"" content=""width=device-width, initial-scale=1"">
<title>Join in MicroCode</title>
<style>
  :root { color-scheme: dark; --bg:#0d0f14; --card:#151922; --text:#e5e7eb; --muted:#9ca3af; --line:rgba(255,255,255,.09); --accent:#3b82f6; }
  * { box-sizing: border-box; }
  body { margin:0; min-height:100vh; display:flex; align-items:center; justify-content:center; background:var(--bg);
         color:var(--text); font:14px/1.5 -apple-system,BlinkMacSystemFont,""Segoe UI"",system-ui,sans-serif; padding:16px; }
  .card { width:100%; max-width:420px; background:var(--card); border:1px solid var(--line); border-radius:14px; padding:28px; }
  h1 { font-size:18px; margin:0 0 4px; }
  p { margin:0 0 18px; color:var(--muted); }
  .code { font:600 13px ui-monospace,Menlo,Consolas,monospace; letter-spacing:.08em; padding:3px 8px; border:1px solid var(--line); border-radius:6px; }
  a.btn { display:block; text-align:center; text-decoration:none; padding:11px 14px; border-radius:9px; font-weight:600; margin-top:10px; }
  .primary { background:var(--accent); color:#fff; }
  .secondary { color:var(--text); border:1px solid var(--line); }
  .small { margin-top:18px; font-size:12px; color:var(--muted); }
  .small a { color:var(--text); }
</style>
</head>
<body>
  <div class=""card"">
    <h1 id=""title"">Join live session</h1>
    <p>Opening MicroCode… Room <span class=""code"" id=""room""></span></p>
    <a class=""btn primary"" id=""open"" href=""#"">Open in MicroCode</a>
    <a class=""btn secondary"" id=""browser"" href=""#"" style=""display:none"">Continue in browser</a>
    <div class=""small"">MicroCode didn't open? <a id=""download"" href=""#"" rel=""noopener"">Install MicroCode</a>, then click “Open in MicroCode” again.</div>
  </div>
  <script>
    const CODE = {{CODE_JSON}}[0];
    const WORKSPACE = {{NAME_JSON}}[0];
    const DOWNLOAD = {{DOWNLOAD_JSON}}[0];
    const BROWSER_ALLOWED = {{BROWSER_ALLOWED}};
    const base = location.origin + location.pathname.replace(/\/(join\/?|index\.html)?$/i, """");
    const joinURL = base + ""/?code="" + encodeURIComponent(CODE);
    const deepLink = ""microcode://collab?token="" + encodeURIComponent(joinURL);
    document.getElementById(""title"").textContent = ""Join “"" + WORKSPACE + ""”"";
    document.getElementById(""room"").textContent = CODE || ""—"";
    document.getElementById(""open"").href = deepLink;
    document.getElementById(""download"").href = DOWNLOAD;
    if (BROWSER_ALLOWED) {
      const b = document.getElementById(""browser"");
      b.href = joinURL; b.style.display = ""block"";
    }
    if (CODE) setTimeout(() => { location.href = deepLink; }, 250);
  </script>
</body>
</html>";
    }
}
